#include "guards.h"
#include "fonts.h"  // generated by tools/ttf2gfx.py at 4x size
#include "smooth.h"

static const uint16_t GOLD_L = RGB565(251, 224, 138);
static const uint16_t GOLD = RGB565(232, 184, 74);
static const uint16_t GOLD_D = RGB565(168, 122, 30);
static const uint16_t RED = RGB565(214, 40, 40);
static const uint16_t GREEN = RGB565(58, 165, 72);
static const uint16_t GREEN_D = RGB565(29, 107, 42);
static const uint16_t INK = RGB565(18, 18, 18);
static const uint16_t PAPER = RGB565(250, 250, 250);

// Card suits about 18px tall, centred on (x, y).
static void spade(Smooth &s, float x, float y, uint16_t c) {
  s.tri(x - 7.6f, y + 0.5f, x + 7.6f, y + 0.5f, x, y - 9, c);
  s.circle(x - 4, y + 2, 4.2f, c);
  s.circle(x + 4, y + 2, 4.2f, c);
  s.tri(x, y + 2, x - 3, y + 9, x + 3, y + 9, c);
}
static void heart(Smooth &s, float x, float y, uint16_t c) {
  s.circle(x - 4.2f, y - 3.5f, 4.8f, c);
  s.circle(x + 4.2f, y - 3.5f, 4.8f, c);
  s.tri(x - 8.8f, y - 2, x + 8.8f, y - 2, x, y + 8.5f, c);
}
static void club(Smooth &s, float x, float y, uint16_t c) {
  s.circle(x, y - 4.5f, 4, c);
  s.circle(x - 4.6f, y + 1.5f, 4, c);
  s.circle(x + 4.6f, y + 1.5f, 4, c);
  s.tri(x, y, x - 3, y + 9, x + 3, y + 9, c);
}
static void diamond(Smooth &s, float x, float y, uint16_t c) {
  float p[] = {x, y - 9, x + 7, y, x, y + 9, x - 7, y};
  s.poly(p, 4, c);
}

static void chipLeaderScene(Smooth &s) {
  s.fill(RGB565_BLACK);
  s.circle(120, 120, 119.5f, GOLD_L, GOLD_D);
  s.circle(120, 120, 113, INK);
  s.circle(120, 120, 84, GOLD_L, GOLD_D);
  s.circle(120, 120, 81, PAPER);

  s.clipR = 81;  // stripes stay inside the white face
  s.rect(0, 86, 240, 24, RED);
  s.rect(0, 126, 240, 22, INK);
  s.clipR = 1e9f;

  float outline[] = {73.5f, 105.5f, 166.5f, 105.5f, 166.5f, 139, 120, 183.5f, 73.5f, 139};
  float body[] = {78.5f, 110.5f, 161.5f, 110.5f, 161.5f, 137, 120, 176.5f, 78.5f, 137};
  s.poly(outline, 5, INK);
  s.poly(body, 5, PAPER);
  s.tri(92, 142, 148, 142, 120, 168, RED);

  s.rect(67, 83, 106, 32, GOLD);
  s.rect(69.5f, 85.5f, 101, 27, RED);
  s.text(&PokerFont4x, 0.25f, "POKER", 120, 99, GOLD);

  spade(s, 84, 66, INK);
  heart(s, 108, 66, RED);
  club(s, 132, 66, INK);
  diamond(s, 156, 66, RED);

  s.arcText(&TitleFont4x, 0.25f, "THE CHIP LEADER", 97, -90, 2.5f, GOLD);

  // Laurel branches around the bottom, gold spade at the base.
  for (int side = 1; side >= -1; side -= 2) {
    float a0 = side == 1 ? 28 : 152, a1 = side == 1 ? 80 : 100;
    s.arc(120, 120, 99, 1.6f, min(a0, a1), max(a0, a1), GREEN_D);
    for (int k = 0; k < 6; k++) {
      float a = a0 + (a1 - a0) * (k + 0.5f) / 6;
      for (int off = -1; off <= 1; off += 2) {
        float r = 99 + off * 6, t = a * DEG_TO_RAD;
        s.ellipse(120 + r * cosf(t), 120 + r * sinf(t), 7.5f, 3.2f, a - 90 * side + off * 35 * side, GREEN);
      }
    }
  }
  spade(s, 120, 217, GOLD);
}

static void chipLeader(Arduino_GFX *gfx) { smoothDraw(gfx, chipLeaderScene); }

const GuardFn GUARDS[] = {chipLeader};
const int GUARD_COUNT = sizeof(GUARDS) / sizeof(GUARDS[0]);
